-- ── Teaching & Learning — Strategy (the-tl-strategy) ──

INSERT INTO scenario_bank (scenario_id, framework_id, dimension_id, dimension_name, target_boundary, target_lower_level, target_upper_level, stem, context_tags, status, source_attribution)
VALUES ('THE-TLS-II-01', 'maturity-the', 'the-tl-strategy', 'Strategy (T&L)', 'incidental-intentional', 'Incidental', 'Intentional', 'Your university has no formal digital strategy for teaching and learning. Individual faculties have adopted various digital tools on an ad-hoc basis, resulting in inconsistent student experiences across programmes. The Vice-Chancellor asks you to address this. What do you do?', '{"subject_area":"universal","institution_level":"higher_education","institution_type":"universal","region":"universal"}'::jsonb, 'active', '{"source_framework":"THE Digital Maturity Index","content_type":"original","attribution_text":"Scenarios created by ReasonLens based on THE Digital Maturity Index framework.","share_alike_applies":false}'::jsonb);

INSERT INTO scenario_bank (scenario_id, framework_id, dimension_id, dimension_name, target_boundary, target_lower_level, target_upper_level, stem, context_tags, status, source_attribution)
VALUES ('THE-TLS-IO-01', 'maturity-the', 'the-tl-strategy', 'Strategy (T&L)', 'integrated-optimised', 'Integrated', 'Optimised', 'Your institution has a well-established digital teaching and learning strategy aligned with its overall strategic plan. Digital learning objectives are embedded in programme validation processes. The PVC Education asks how you can take this to the next level. How do you approach this?', '{"subject_area":"universal","institution_level":"higher_education","institution_type":"universal","region":"universal"}'::jsonb, 'active', '{"source_framework":"THE Digital Maturity Index","content_type":"original","attribution_text":"Scenarios created by ReasonLens based on THE Digital Maturity Index framework.","share_alike_applies":false}'::jsonb);

-- ── Teaching & Learning — People & Culture (the-tl-people) ──

INSERT INTO scenario_bank (scenario_id, framework_id, dimension_id, dimension_name, target_boundary, target_lower_level, target_upper_level, stem, context_tags, status, source_attribution)
VALUES ('THE-TLP-II-01', 'maturity-the', 'the-tl-people', 'People & Culture (T&L)', 'incidental-intentional', 'Incidental', 'Intentional', 'Academic staff across your institution have widely varying levels of digital teaching skills. Some are early adopters while many others avoid digital tools entirely. There is no coordinated approach to building digital capability among teaching staff. What do you do?', '{"subject_area":"universal","institution_level":"higher_education","institution_type":"universal","region":"universal"}'::jsonb, 'active', '{"source_framework":"THE Digital Maturity Index","content_type":"original","attribution_text":"Scenarios created by ReasonLens based on THE Digital Maturity Index framework.","share_alike_applies":false}'::jsonb);

INSERT INTO scenario_bank (scenario_id, framework_id, dimension_id, dimension_name, target_boundary, target_lower_level, target_upper_level, stem, context_tags, status, source_attribution)
VALUES ('THE-TLP-IO-01', 'maturity-the', 'the-tl-people', 'People & Culture (T&L)', 'integrated-optimised', 'Integrated', 'Optimised', 'Your institution has a structured digital capability framework for teaching staff, with mandatory training and support pathways linked to promotion criteria. Engagement is high and feedback is positive. You are now asked to ensure your approach is sector-leading. What do you do?', '{"subject_area":"universal","institution_level":"higher_education","institution_type":"universal","region":"universal"}'::jsonb, 'active', '{"source_framework":"THE Digital Maturity Index","content_type":"original","attribution_text":"Scenarios created by ReasonLens based on THE Digital Maturity Index framework.","share_alike_applies":false}'::jsonb);

