INSERT INTO scenario_bank (scenario_id, framework_id, dimension_id, dimension_name, target_boundary, target_lower_level, target_upper_level, stem, context_tags, status, source_attribution)
VALUES ('THE-TLT-II-01', 'maturity-the', 'the-tl-technology', 'Technology (T&L)', 'incidental-intentional', 'Incidental', 'Intentional', 'Your institution''s learning management system is outdated, and departments have independently adopted different platforms and tools to fill gaps. Students complain about having to use too many disconnected systems. How do you approach this?', '{"subject_area":"universal","institution_level":"higher_education","institution_type":"universal","region":"universal"}'::jsonb, 'active', '{"source_framework":"THE Digital Maturity Index","content_type":"original","attribution_text":"Scenarios created by ReasonLens based on THE Digital Maturity Index framework.","share_alike_applies":false}'::jsonb);

INSERT INTO scenario_bank (scenario_id, framework_id, dimension_id, dimension_name, target_boundary, target_lower_level, target_upper_level, stem, context_tags, status, source_attribution)
VALUES ('THE-TLT-IO-01', 'maturity-the', 'the-tl-technology', 'Technology (T&L)', 'integrated-optimised', 'Integrated', 'Optimised', 'Your institution has a fully integrated digital learning ecosystem with single sign-on, an LMS tightly coupled with lecture capture and assessment tools, and robust mobile access. The CIO asks you to define the next phase of technology investment for teaching. What do you do?', '{"subject_area":"universal","institution_level":"higher_education","institution_type":"universal","region":"universal"}'::jsonb, 'active', '{"source_framework":"THE Digital Maturity Index","content_type":"original","attribution_text":"Scenarios created by ReasonLens based on THE Digital Maturity Index framework.","share_alike_applies":false}'::jsonb);

