INSERT INTO scenario_bank (scenario_id, framework_id, dimension_id, dimension_name, target_boundary, target_lower_level, target_upper_level, stem, context_tags, status, source_attribution)
VALUES ('THE-TLD-IO-01', 'maturity-the', 'the-tl-data', 'Data (T&L)', 'integrated-optimised', 'Integrated', 'Optimised', 'Your institution has a mature learning analytics platform that provides real-time dashboards to personal tutors and programme leaders. Predictive models identify at-risk students with reasonable accuracy. Senior leadership asks how to move from good to world-class in learning analytics. What do you do?', '{"subject_area":"universal","institution_level":"higher_education","institution_type":"universal","region":"universal"}'::jsonb, 'active', '{"source_framework":"THE Digital Maturity Index","content_type":"original","attribution_text":"Scenarios created by ReasonLens based on THE Digital Maturity Index framework.","share_alike_applies":false}'::jsonb);

