INSERT INTO scenario_responses (scenario_id, response_key, response_text, maps_to_level_name, maps_to_level_order, is_attractive_nuisance, nuisance_explanation, discriminating_presence, discriminating_absence)
VALUES ('THE-TLS-II-01', 'A', 'Let faculties continue to choose their own tools. If something is working for them, there is no reason to change it. Focus your attention on more pressing institutional issues.', 'Incidental', 1, false, NULL, NULL, NULL);
INSERT INTO scenario_responses (scenario_id, response_key, response_text, maps_to_level_name, maps_to_level_order, is_attractive_nuisance, nuisance_explanation, discriminating_presence, discriminating_absence)
