INSERT INTO scenario_responses (scenario_id, response_key, response_text, maps_to_level_name, maps_to_level_order, is_attractive_nuisance, nuisance_explanation, discriminating_presence, discriminating_absence)
VALUES ('THE-TLS-II-01', 'D', 'Create a digital T&L strategy that is benchmarked against global leaders, incorporates continuous improvement cycles informed by sector data and student outcomes, and positions the institution as a reference model for others through published case studies and peer review.', 'Optimised', 4, false, NULL, NULL, NULL);

